function interact(){if(player.held){const o=player.held;player.held=null;o.held=false;o.x=player.x+player.w/2-o.w/2+player.facing*25;o.y=player.y+9;o.vx=player.vx*.6;o.vy=-60;return}const o=nearestThing();if(o&&o.mass<=4.2){o.held=true;player.held=o;o.vx=o.vy=0}else if(o){checkpointToast=2;statusEl.textContent='Too heavy to lift — shove it or use the machinery!'}}
function toss(){if(!player.held)return;const o=player.held;player.held=null;o.held=false;o.x=player.x+player.w/2-o.w/2+player.facing*22;o.y=player.y+7;o.vx=player.facing*430+player.vx*.5;o.vy=-410;o.awake=true}
function supportCollision(body,dt,isPlayer=false){body.onGround=false;const oldBottom=body.y+body.h;body.x+=body.vx*dt;
 for(const p of platforms){if(body.x+body.w>p.x&&body.x<p.x+p.w&&body.y+body.h>p.y&&body.y<p.y+p.h){if(body.vx>0)body.x=p.x-body.w;else if(body.vx<0)body.x=p.x+p.w;body.vx=0}}
 if(!isPlayer){for(const g of [gate,gate2])if(!g.open&&body.x+body.w>g.x&&body.x<g.x+g.w&&body.y+body.h>g.y&&body.y<g.y+g.h){if(body.vx>0)body.x=g.x-body.w;else if(body.vx<0)body.x=g.x+g.w;body.vx=0}}
 body.y+=body.vy*dt;
 for(const p of platforms){if(body.x+body.w>p.x&&body.x<p.x+p.w&&oldBottom<=p.y+8&&body.y+body.h>=p.y&&body.vy>=0){body.y=p.y-body.h;body.vy=0;body.onGround=true}}
 if(!isPlayer){const surface=beam.y+Math.tan(beam.angle)*(body.x+body.w/2-beam.x),local=body.x+body.w/2-beam.x;if(Math.abs(local)<beam.len/2+body.w/2&&oldBottom<=surface+12&&body.y+body.h>=surface&&body.vy>=0){body.y=surface-body.h;body.onGround=true;const tangentVy=beam.omega*local;if(Math.abs(tangentVy)>75){body.vy=tangentVy;body.onGround=false}else body.vy=0;body.vx+=beam.omega*local*.18}}
 if(isPlayer&&body.y+body.h>=500){body.y=500-body.h;body.vy=0;body.onGround=true}
