}
function collideBodies(){for(let i=0;i<things.length;i++)for(let j=i+1;j<things.length;j++){const a=things[i],b=things[j];if(a.held||b.held||!overlap(a,b))continue;const dx=(a.x+a.w/2)-(b.x+b.w/2),dy=(a.y+a.h/2)-(b.y+b.h/2);if(Math.abs(dx)>Math.abs(dy)*.8){const push=(Math.abs(dx)<1?1:Math.sign(dx))*(Math.min(a.x+a.w-b.x,b.x+b.w-a.x)/2);a.x+=push;b.x-=push;const av=a.vx,bv=b.vx;a.vx=(av*(a.mass-b.mass)+2*b.mass*bv)/(a.mass+b.mass);b.vx=(bv*(b.mass-a.mass)+2*a.mass*av)/(a.mass+b.mass)}else if(dy<0){a.y-=Math.min(a.y+a.h-b.y,.6);a.vy=Math.min(a.vy,b.vy);a.onGround=true}else{b.y-=Math.min(b.y+b.h-a.y,.6);b.vy=Math.min(a.vy,b.vy);b.onGround=true}}}
function update(dt){if(won)return;elapsed+=dt;if(pressed.interact)interact();if(pressed.throw)toss();
 const dir=(input.right?1:0)-(input.left?1:0);if(dir)player.facing=dir;const carrying=player.held?0.76:1;player.vx+=(dir*900*dt);player.vx*=Math.pow(player.onGround?.78:.93,dt*60);player.vx=clamp(player.vx,-220*carrying,220*carrying);if(pressed.jump&&player.onGround){player.vy=-475;player.onGround=false}player.vy=Math.min(900,player.vy+GRAVITY*dt);supportCollision(player,dt,true);player.anim+=Math.abs(player.vx)*dt*.045;
