 if(player.held){const o=player.held,center=o.x+o.w/2;if(center>plate1.x&&center<plate1.x+plate1.w&&Math.abs(player.y+player.h-plate1.y)<14)plate1.weight+=o.mass;if(center>plate2.x&&center<plate2.x+plate2.w&&Math.abs(player.y+player.h-plate2.y)<14)plate2.weight+=o.mass}
