function drawGate(g, number) {
  const lift = g.anim * (g.h + 20);
  if (lift < g.h - 2) {
    ctx.save(); ctx.beginPath(); ctx.rect(g.x - 12, 60, g.w + 24, g.h + 40); ctx.clip();
    const y = g.y - lift;
    rect(g.x - 7, y - 10, g.w + 14, 12, '#2b3e50');
    rect(g.x, y, g.w, g.h, '#2f4458');
    for (let yy = y + 8; yy < y + g.h; yy += 25) {
      rect(g.x + 4, yy, g.w - 8, 5, '#7f9395');
      rect(g.x + g.w / 2 - 3, yy + 7, 6, 8, '#b3a878');
    }
    rect(g.x + 5, y + g.h - 34, g.w - 10, 22, '#283b4c');
    rect(g.x + g.w / 2 - 5, y + g.h - 29, 10, 12, g.open ? '#55d9c4' : '#efb14d');
    ctx.restore();
  }
  // gate frame
  rect(g.x - 12, 126, 8, 49, '#354b5d'); rect(g.x + g.w + 4, 126, 8, 49, '#354b5d');
  rect(g.x - 12, 166, g.w + 24, 9, '#c69855');
  ctx.fillStyle = g.open ? '#a8ffe9' : '#ffe2a0';
  ctx.font = 'bold 10px monospace'; ctx.fillText(g.open ? 'OPEN' : 'LOCK ' + number, g.x - 14, 118);
}

